def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

N = 2021
divisors = get_divisors(N)
print(f"Divisors of {N}: {divisors}")
print(f"Possible sizes |K| >= 3 based on subgroups: {[d for d in divisors if d >= 3]}")

