def check_condition(K, N):
    K_set = set(K)
    for p in K:
        for q in K:
            S = p + q
            found_r = False
            # We need S == 2r (mod N) for some r in K
            for r in K:
                if (S - 2 * r) % N == 0:
                    found_r = True
                    break
            if not found_r:
                print(f"Failed for p={p}, q={q}. Sum S={S}. Required 2r must be congruent to {S} mod {N}.")
                print(f"Possible 2r mod {N} are: {[2*r % N for r in K]}")
                return False
    return True

K = [0, 1, 43, 44]
N = 2021
result = check_condition(K, N)
print(f"\nTest Result for K={K}: {result}")
